public class RedisRateLimiter {
    private final RedisTemplate<String, String> redisTemplate;
    private final RedisScript<Long> limitScript;

    public RedisRateLimiter(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
        this.limitScript = new DefaultRedisScript<>(
            "local key = KEYS[1]\n" +
            "local limit = tonumber(ARGV[1])\n" +
            "local current = tonumber(redis.call('get', key) or '0')\n" +
            "if current + 1 > limit then\n" +
            "    return 0\n" +
            "else\n" +
            "    redis.call('INCRBY', key, 1)\n" +
            "    if current == 0 then\n" +
            "        redis.call('EXPIRE', key, 1)\n" +
            "    end\n" +
            "    return 1\n" +
            "end",
            Long.class
        );
    }

    public boolean isAllowed(String userId, int limit) {
        String key = "rate_limit:" + userId;
        Long result = redisTemplate.execute(limitScript, Collections.singletonList(key), String.valueOf(limit));
        return result != null && result == 1L;
    }
}
